    The size of each leaf (non-dict/list/set) is 1.
    """
def objsize(`obj: Any) -> object {
    assert isinstance(`obj, (dict, list, set)) , `obj;
    if not `obj {
        return 0;
    }
    if isinstance(`obj, dict) {
        `obj = `obj.values();
    }
    elem = next(iter(`obj));
