            ch = str(inp[i]);
        }
        digit: int;
        if ch == 'A' { digit = 10; }
        elif ch == 'B' { digit = 11; }
        elif ch == 'C' { digit = 12; }
        elif ch == 'D' { digit = 13; }
        elif ch == 'E' { digit = 14; }
        elif ch == 'F' { digit = 15; }
        elif ch != int(ch) {
