```jac
"""Time: O(n log n). Space: O(1)."""
def is_unique_with_no_extra_space(s: str) -> bool {
    if len(s) == 1 {
        return True;
    }
    s = "".join(sorted(s));
    for char in s {
        begin = 0;
        end = len(s) - 1;
        while begin < end {
            middle = begin + (end - begin) // 2;
            if s[middle] == char {
                if middle >= 1 and s[middle - 1] == char {
                    return False;
                }
                if middle <= len(s) - 2 and s[middle + 1] == char {
                    return False;
                }
                break;
            } elif s[middle] > char {
                begin = middle + 1;
            } else {
                end = middle - 1;
            }
        }
    }
    return True;
}
