def calculateHammingSyndrom(byte: list[int]) -> dict[str, int] {
    S0 = str(
        int(byte[1])
        ^ int(byte[3])
        ^ int(byte[5])
        ^ int(byte[7])
        ^ int(byte[9])
        ^ int(byte[11])
    );
    S1 = str(
